    g_bytes += n;
    if (void* p = std::malloc(n)) {
        return p;
    }
    throw std::bad_alloc();
}

void operator delete(void* p) noexcept { std::free(p); }
void operator delete(void* p, std::size_t) noexcept { std::free(p); }

long allocs_before = 0;
long bytes_before = 0;

void start() {
    allocs_before = g_allocs;
    bytes_before = g_bytes;
}

void report(const char* what) {  // a std::string label could allocate too
    long allocs = g_allocs - allocs_before;  // read both counters before printing
    long bytes = g_bytes - bytes_before;
    std::cout << what << ": " << allocs << " allocs, " << bytes << " bytes\n";
}

int main() {
    start();
    std::string symbol = "ESZ5";                      // 4 chars: inside the object
    report("symbol");
    start();
    std::string desk = "rates-desk-nyc-01";           // 17 chars: on the heap
    report("desk");
    start();
    std::string log;
    for (int i = 0; i < 100; ++i) {
        log += 'x';                                   // capacity 15, 30, 60, 120
    }
    report("log of 100 chars");
    start();
    std::map<int, double> levels = {{10000, 5}, {10025, 3}, {10050, 8}};
    report("map of 3 levels");
    start();
    std::vector<bool> halted(1000);                   // 1000 flags, packed as bits
    report("vector<bool> of 1000");
    start();
    std::vector<char> halted_bytes(1000);             // 1000 flags, a byte each
    report("vector<char> of 1000");

    auto flag = halted[7];                            // a proxy, not a bool
    flag = true;                                      // writes the bit inside halted
    std::cout << "halted[7] is now " << halted[7] << '\n';
    return 0;
}

