#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <new>
#include <vector>

long g_allocs = 0;  // calls to operator new
long g_bytes = 0;   // bytes they asked for

void* operator new(std::size_t n) {
    ++g_allocs;
    g_bytes += n;
    if (void* p = std::malloc(n)) {
        return p;
    }
    throw std::bad_alloc();
}

void operator delete(void* p) noexcept { std::free(p); }
void operator delete(void* p, std::size_t) noexcept { std::free(p); }

struct Order {
    int64_t id;
    double price;
    int32_t qty;
};

struct OrderPool {
    std::vector<Order> orders;    // every order lives here
    std::vector<int> free_slots;  // indexes of the free orders, used as a stack

    explicit OrderPool(int capacity) : orders(capacity) {
        free_slots.reserve(capacity);
        for (int i = capacity - 1; i >= 0; --i) {
            free_slots.push_back(i);
        }
    }

    int acquire() {  // a free slot, or -1 when every slot is in use
        if (free_slots.empty()) {
            return -1;
        }
        int slot = free_slots.back();
        free_slots.pop_back();
        return slot;
    }

    void release(int slot) {
        free_slots.push_back(slot);  // never past the reserved capacity
    }
};

int main() {
    long allocs = g_allocs;
    Order* live[3] = {};
    for (int i = 0; i < 10'000; ++i) {
        delete live[i % 3];  // nullptr for the first 3 messages: deletes nothing
        live[i % 3] = new Order{i, 100.0 + i % 8 * 0.25, 100};
    }
    std::cout << "new and delete: " << g_allocs - allocs << " allocs\n";
    for (Order* o : live) delete o;

    long before_pool = g_allocs;
    OrderPool pool(64);
    allocs = g_allocs;
    int slots[3] = {-1, -1, -1};
    for (int i = 0; i < 10'000; ++i) {
        if (slots[i % 3] >= 0) {
            pool.release(slots[i % 3]);
        }
        slots[i % 3] = pool.acquire();
        pool.orders[slots[i % 3]] = Order{i, 100.0 + i % 8 * 0.25, 100};
    }
    std::cout << "pool: " << allocs - before_pool << " allocs to set up, " << g_allocs - allocs << " for 10000 messages\n";

    int64_t id_sum = pool.orders[slots[0]].id + pool.orders[slots[1]].id + pool.orders[slots[2]].id;
    std::cout << "live order ids add up to " << id_sum << '\n';
    return 0;
}

