#include <array>
#include <cstddef>
#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <map>
#include <memory_resource>
#include <new>
#include <vector>

long g_allocs = 0;  // calls to operator new
long g_bytes = 0;   // bytes they asked for

void* operator new(std::size_t n) {
    ++g_allocs;
    g_bytes += n;
    if (void* p = std::malloc(n)) {
        return p;
    }
    throw std::bad_alloc();
}

void* operator new(std::size_t n, std::align_val_t align) {  // std::pmr asks through this one
    ++g_allocs;
    g_bytes += n;
    std::size_t a = static_cast<std::size_t>(align);
    if (void* p = std::aligned_alloc(a, (n + a - 1) / a * a)) {  // a size that's a multiple of a
        return p;
    }
    throw std::bad_alloc();
}

void operator delete(void* p) noexcept { std::free(p); }
void operator delete(void* p, std::size_t) noexcept { std::free(p); }
void operator delete(void* p, std::align_val_t) noexcept { std::free(p); }
void operator delete(void* p, std::size_t, std::align_val_t) noexcept { std::free(p); }

int main() {
    int batches, per_batch;
    std::cin >> batches >> per_batch;
    std::array<std::byte, 32 * 1024> buffer;  // 32 KB on the stack

    long allocs = g_allocs;
    std::size_t levels = 0;
    for (int batch = 0; batch < batches; ++batch) {
        std::pmr::monotonic_buffer_resource arena(buffer.data(), buffer.size());
        std::pmr::vector<int64_t> ids(&arena);
        ids.reserve(per_batch);
        std::pmr::map<int, int> qty_at(&arena);  // quantity at each price, in cents
        for (int i = 0; i < per_batch; ++i) {
            ids.push_back(int64_t{batch} * per_batch + i);
            qty_at[5000 + i % 5 * 25] += 10;
        }
        levels += qty_at.size();
    }
    std::cout << batches << " batches in the arena: " << g_allocs - allocs << " allocs, " << levels << " levels\n";

    std::pmr::monotonic_buffer_resource strict(buffer.data(), buffer.size(), std::pmr::null_memory_resource());
    std::cout << "strict arena, " << per_batch * 10 << " ids: ";
    try {
        std::pmr::vector<int64_t> ids(per_batch * 10, 0, &strict);
        std::cout << "fits\n";
    } catch (const std::bad_alloc&) {
        std::cout << "bad_alloc\n";
    }
    return 0;
}
